insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('intake-aftermarket','bpy','Aftermarket intake install','Engine','air intake',array['cold air intake','cai','carbonio','cts intake','injen','k&n','neuspeed p-flo','ie intake','intake']::text[],true,'1–2 hr',2) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('downpipe','bpy','Downpipe upgrade','Engine','exhaust',array['downpipe','dp','test pipe','high flow cat','catless','turbo back']::text[],true,'3–4 hr',3) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('catback','bpy','Cat-back exhaust install','Engine','exhaust',array['cat back','catback','exhaust','muffler','resonator','tips','borla','milltek']::text[],true,'2–3 hr',2) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('intake-aftermarket',$j${"id": "intake-aftermarket", "title": "Aftermarket intake install", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "intake-hero", "alsoFits": "2006–08.5 GTI/Jetta/Eos 2.0T FSI · 06–08 A3 8P · 08 TT 8J (same engine-cover airbox)", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which intake are you installing?", "hint": "They are not all the same job. Most kits remove the engine cover entirely and put a heat-shielded filter on the battery tray. APR's Carbonio keeps the stock airbox and engine cover.", "options": [{"id": "ie", "label": "Integrated Engineering (IE)", "when": "Full kit: pipe, heat shield, filter. Engine cover comes off."}, {"id": "neuspeed", "label": "Neuspeed P-Flo", "when": "Full kit with heat shield on three battery-tray posts. Engine cover comes off."}, {"id": "carbonio", "label": "APR Carbonio (Stage 1 / Stage 2)", "when": "Keeps the engine cover. Stage 1 swaps the lower airbox and scoop; Stage 2 swaps the turbo inlet pipe."}, {"id": "other", "label": "Other sealed-box cone kit (CTS, Injen, K&N…)", "when": "Same shape of job as IE. Follow your kit's sheet for hardware."}]}, "glance": {"timeFirst": "1–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$250–600", "risk": "MAF sensor is fragile · clamps at the turbo are awkward", "why": "On a stock turbo, an intake is mostly sound and throttle feel: the forums are blunt about that. Pair it with a tune or a bigger turbo and it starts to earn its keep. Either way it's a satisfying afternoon that makes the car sound like it means it.", "note": "Manufacturer sheets say an hour. Owners report two, mostly spent making the turbo-side clamp reachable."}, "heroCap": "Air path after the swap: filter under a heat shield on the battery tray, metal pipe past the factory MAF sensor, silicone coupler onto the turbo inlet. The engine cover is gone.", "lifespan": {"title": "When owners do this", "headline": ["Usually the first engine mod, often with a Stage 1 tune"], "earliest": null, "detail": "There's nothing to wear out; owners do it for sound and looks first, and because a tune plus intake is the classic first step. Oiled cotton filters want cleaning every 20–30k; dry paper elements get replaced.", "factors": ["Stage 1/2 tune", "K04 or bigger turbo (then it matters for real)", "You miss induction noise"], "inspect": ["Cotton filter: clean and re-oil every 20–30k miles, lightly. Over-oiling fouls the MAF."], "confidence": {"level": "community", "n": 4, "note": "Forum consensus and vendor notes. Power claims are the vendors'."}}, "should": {"yesIf": ["You want induction sound and sharper throttle feel", "You're tuned or going to be", "You have or want to delete the engine cover look", "You accept that dyno gains on a stock turbo are small"], "codes": [], "notes": ["The factory MAF sensor moves to the new pipe. Every good kit sizes its pipe to the factory MAF housing so fuel trims stay right; a pipe that doesn't will throw codes. That's why the cheap eBay pipe is a bad idea.", {"text": "Carbonio Stage 1 is the mild version: the engine cover and factory filter stay, only the lower airbox and scoop change. Owners who wanted full-intake gains were disappointed; owners who wanted to keep the cover were happy. Know which one you are.", "only": ["carbonio"]}], "confidence": {"level": "high", "n": 4, "note": "Method agrees across two manufacturer PDFs and two owner install threads."}}, "parts": [{"tier": "aftermarket", "name": "Intake kit", "pn": "see options below", "note": "Pipe, coupler(s), filter, heat shield, clamps, isolator hardware", "price": "$250–600", "links": []}, {"tier": "oe", "name": "Turbo inlet o-ring / gasket", "pn": "if reusing the factory inlet pipe", "note": "Only if it's cracked", "price": "$5", "links": [], "only": ["carbonio"]}, {"tier": "oe", "name": "Small zip ties, silicone spray", "pn": "—", "note": "For routing the MAF harness and seating grommets", "price": "$5", "links": []}], "aftermarket": [{"name": "Integrated Engineering carbon/aluminium intake", "note": "Complete, well-documented kit; the install PDF is the best of the group. Velocity stack under a powder-coated heat shield.", "price": "$450–550", "signal": "Best documented", "links": [{"store": "IE install guide (PDF)", "url": "https://pbie.s3.amazonaws.com/guides/IE%20MK5%20FSI%20INTAKE%20INSTALL%20IEINCB4.pdf"}]}, {"name": "Neuspeed P-Flo", "note": "The long-time forum default. Aluminium heat shield, choice of oiled cotton or dry paper filter, CARB exempt. Pipe matched to the factory MAF.", "price": "$300–350", "signal": "Forum favorite", "links": []}, {"name": "APR Carbonio Stage 1 (+ Stage 2 pipe)", "note": "Carbon fibre, keeps the engine cover. Stage 1 is the airbox/scoop; Stage 2 adds the turbo inlet pipe, which owners found fiddlier and prone to sagging without its centre support.", "price": "$300–600", "signal": "Best looking, mildest", "links": []}, {"name": "CTS Turbo", "note": "Sealed airbox with scoop, 2.75\" pipe, factory MAF position, bungs for their BOSS kit. Popular with the tuned/K04 crowd.", "price": "$300–400", "signal": "Tuner pick", "links": [{"store": "CTS Turbo", "url": "https://ctsturbo.com/product/cts-turbo-mk5-mk6-s3-air-intake-system/"}]}], "tools": [{"name": "T20 and T25 Torx", "note": "kits and cars disagree on which; bring both"}, {"name": "Flat screwdriver (inlet clips), Phillips", "only": ["ie", "neuspeed", "other", "carbonio"]}, {"name": "Pliers or spring-clamp tool for the turbo inlet hose clamp"}, {"name": "4mm hex (MAF screws in the new pipe), 10mm wrench (isolator stud)", "only": ["ie", "neuspeed", "other"]}, {"name": "5mm hex (lower airbox bolt), T30 (inlet pipe bolt), 10mm socket", "only": ["carbonio"]}, {"name": "Screwdriver or ¼\" driver for worm clamps; a mirror helps at the turbo"}], "before": ["Engine cold. You'll have your hands next to the turbo.", "Lay the kit out and check every clamp and coupler against the parts list before you take anything apart.", "The MAF sensor's element is exposed and delicate. Handle it by the housing, never touch the wires, and keep it off the ground."], "steps": [{"n": 1, "title": "Open up the stock intake", "blocks": [{"t": "text", "b": "Pull the inlet cover off the radiator support (a locking tab each side). Separate the two halves of the air inlet by pressing their tabs. Unplug the MAF sensor. Flip the two clips on the turbo inlet pipe with a flat screwdriver and pull it off the engine cover.", "only": ["ie", "neuspeed", "other"]}, {"t": "text", "b": "Unscrew the eight to ten Phillips screws holding the airbox top to its bottom (the engine cover is the top). Unplug the MAF and release the hose clamp between the MAF and the turbo inlet pipe. Lift the top off and set it aside; you're keeping it.", "only": ["carbonio"]}]}, {"n": 2, "title": "Engine cover off, radiator-support inlet off", "only": ["ie", "neuspeed", "other"], "blocks": [{"t": "text", "b": "Grab the cover at the corners and pull straight up off its four grommets; it can take real leverage. Then remove the last piece of the inlet from the radiator support (two T25 screws). Squeeze the turbo inlet hose clamp with pliers and pull the factory inlet pipe off the turbo."}, {"t": "ill", "id": "airbox-bay", "cap": "Everything that comes out. The MAF sensor (blue) is the one part you keep."}]}, {"n": 2, "title": "Lower airbox and scoop off", "only": ["carbonio"], "blocks": [{"t": "text", "b": "With the top gone, remove the two Torx screws holding the inlet scoop (T25 on most cars, whatever APR's sheet says). Remove the 5mm hex bolt holding the lower airbox to the car, then pull the lower airbox up firmly off its two rubber-grommeted studs."}]}, {"n": 3, "title": "Move the MAF sensor to the new pipe", "only": ["ie", "neuspeed", "other"], "blocks": [{"t": "text", "b": "Two T20 screws hold the MAF in the engine cover. Lift it out by the housing. Set it into the new pipe's MAF boss in the same orientation (arrow or airflow marking toward the turbo) and fix it with the kit's button-head screws (4mm hex on IE). Snug, not tight; the housing is plastic."}, {"t": "warn", "b": "If the sensor is dropped or the wires touched, you'll chase a rough idle for weeks. It's the one fragile part in this job."}]}, {"n": 3, "title": "Fit the Carbonio airbox and scoop", "only": ["carbonio"], "blocks": [{"t": "text", "b": "Seat the carbon lower airbox onto the two studs, fit APR's scoop with the two Torx screws, and put the original engine cover back on top with the Phillips screws and the factory filter. Reconnect the MAF and the inlet hose clamp. Stage 1 is done; if you have the Stage 2 pipe, continue."}]}, {"n": 4, "title": "Coupler onto the turbo", "only": ["ie", "neuspeed", "other"], "blocks": [{"t": "text", "b": "Slip the kit's silicone coupler onto the turbo inlet with its clamp loose. If the factory breather hose used to plug into the inlet pipe, fit the kit's plug into that coupler port with its one-time clamp and crimp it tight. Leave the main clamps loose for now."}]}, {"n": 4, "title": "Stage 2: swap the turbo inlet pipe", "only": ["carbonio"], "blocks": [{"t": "text", "b": "Remove the T30 bolt securing the factory inlet pipe at the rear of the head (APR calls it T25; it's T30), unclip the breather hose, and release the hose clamp at the turbo coupler with pliers; it's a tight reach. Fit the carbon pipe onto the coupler, reconnect the breather, and start the 10mm bolt with its rubber washer at the rear mount."}, {"t": "note", "b": "The pipe passes close to the brake fluid reservoir and brake lines. If it touches, loosen the turbo-side clamp and push the pipe further onto the coupler. Fit the centre support APR supplies; without it the pipe sags onto the brake lines and vibrates."}]}, {"n": 5, "title": "Pipe and isolator", "only": ["ie", "neuspeed", "other"], "blocks": [{"t": "text", "b": "Fit the rubber isolator stud to the pipe's bracket (washer and 10mm nut, hand tight), then guide the pipe into the turbo coupler with its clamp loose. Pass the isolator stud through the vacuum-pump bracket on the side of the head and start its nut. Nothing tight yet."}]}, {"n": 6, "title": "Heat shield and filter", "only": ["ie", "neuspeed", "other"], "blocks": [{"t": "text", "b": "Press the kit's rubber grommets into the heat shield (flat side down), fit the velocity-stack coupler to the shield with its clamp loose, and lower the shield onto the battery-tray posts (two on IE, three on Neuspeed) until the grommets click over. Join the shield coupler to the pipe. Wipe the inside lip of the filter with cleaner so it grips, then clamp it to the stack."}, {"t": "ill", "id": "intake-hero", "cap": "Final layout. Every clamp is still loose until the whole run sits relaxed."}]}, {"n": 7, "title": "Align, then tighten everything", "caution": true, "only": ["ie", "neuspeed", "other"], "blocks": [{"t": "text", "b": "Stand back and look: the pipe should sit straight with no coupler under tension and nothing touching the strut brace, coolant lines or the battery. Adjust, then tighten all clamps firmly (a screwdriver on worm clamps; no impact), both isolator nuts with a 10mm, and plug the MAF back in. Tug the whole thing; nothing should move."}, {"t": "warn", "b": "A coupler clamped under tension slips off the turbo inlet under boost, and the car eats unfiltered air until you notice. Relaxed first, tight second."}]}, {"n": 8, "title": "Start it and listen", "blocks": [{"t": "text", "b": "Start the engine. Rev gently and listen for hissing at the couplers. Let it idle for a couple of minutes; a stumble that settles is the ECU adapting, one that doesn't is a MAF problem. Take it for a drive and re-check every clamp when you're back."}]}], "alsoReplace": [{"name": "PCV / breather system", "why": "You're handling the breather hose anyway. A tired FSI PCV is a known oil-consumption culprit; a revision or a catch-can install shares this access."}, {"name": "Turbo inlet pipe coupler", "why": "If the factory coupler at the turbo is hardened or cracked, the kit's silicone one replaces it; check before you assume you're reusing it.", "only": ["carbonio"]}], "check": {"tab": "Which kit?", "title": "Which kind of intake suits you?", "illId": "intake-hero", "illCap": "Full kit (left) replaces the cover; Carbonio (right) keeps it.", "rows": [{"see": "Stock turbo, maybe Stage 1, want sound and looks", "means": "You're buying character, not horsepower. Any well-made kit does this.", "do": "Neuspeed or IE if you like the exposed-engine look; Carbonio Stage 1 if you want the cover."}, {"see": "K04 or bigger turbo, Stage 2+", "means": "Now the stock box is a real restriction.", "do": "Full kit: IE, CTS or Neuspeed. Skip Carbonio Stage 1."}, {"see": "Salt-belt daily, don't want to oil filters", "means": "Oiled cotton needs care and can foul the MAF.", "do": "Pick a kit with a dry filter option (Neuspeed) or budget for careful oiling."}], "c": {"level": "community", "n": 4, "note": "Forum consensus; vendor claims noted as claims."}}, "aftercare": ["Re-tighten clamps after the first heat cycle.", "Oiled filter: clean and lightly re-oil every 20–30k. Dry filter: replace per the maker.", "Rough idle after install: check the MAF plug and that the pipe's MAF boss is the right diameter for your sensor."], "disagreements": [{"topic": "How much does it do?", "pos": "Vendors: 9–15 whp. Owners: 'louder, not faster' on a stock turbo.", "call": "Both are right for different cars. We say so."}, {"topic": "T20 or T25? T25 or T30?", "pos": "APR's sheet vs the owner who installed it; Pelican vs FCP on the stock screws.", "call": "Bring the set."}, {"topic": "Is Carbonio Stage 1 an intake?", "pos": "Forum argument since 2008.", "call": "It's the mild option. Fine if you want the cover; not the pick for a K04."}], "sources": ["IE Cold Air Intake install guide (PDF)", "Neuspeed P-Flo install guide and product pages", "VWVortex APR/Carbonio Stage 1 & 2 install thread", "GolfMKV and Golfmk6 Carbonio threads", "CTS Turbo product page", "VWVortex and Golfmk6 intake-value threads"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('downpipe',$j${"id": "downpipe", "title": "Downpipe upgrade", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "downpipe-hero", "alsoFits": "2006–09 GTI · 05–10 Jetta 2.0T · 06–08 A3 8P · Mk6 GTI (TSI: top-side access differs)", "category": "Engine", "kind": "upgrade", "variants": {"question": "What's the downpipe connecting to?", "hint": "The stock cat-back has a 60mm slip joint. A 3-inch aftermarket downpipe needs a reducer to meet it, or mates directly to a 3-inch cat-back.", "options": [{"id": "stockcb", "label": "Stock cat-back", "when": "You'll use the kit's reducer adapter and clamps"}, {"id": "aftcb", "label": "3-inch aftermarket cat-back", "when": "Direct slip-fit or V-band, no adapter"}]}, "glance": {"timeFirst": "3–4 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$500–1,000 + tune", "risk": "Seized nuts and O2 sensors · hot, heavy pipe · legality", "why": "The factory downpipe necks down right after the turbo and carries a dense cat. A 3-inch pipe with a high-flow cat lets the turbo breathe out, which is where a tuned FSI finds its next 20–30 hp and a lot of its sound.", "note": "Vendors say a weekend for an experienced tech. Owners say the four turbo nuts and two O2 sensors decide the day."}, "heroCap": "Turbo flange (4 nuts) → flex → cat → bracket on the crossmember → slip joint to the cat-back. Two O2 sensors live in it. The chassis braces have to come off to get it out.", "lifespan": {"title": "When owners do this", "headline": ["With, or right after, a Stage 2 tune"], "earliest": null, "detail": "Stage 2 software assumes a high-flow downpipe. Doing the pipe without the tune gives you sound and a likely check-engine light; the tune without the pipe leaves power on the table. Owners pair them.", "factors": ["Stage 2 tune planned", "Cat-back already fitted", "Catalytic converter failing anyway (P0420)"], "inspect": ["Re-check all nuts and clamps after 1–2 days of driving"], "confidence": {"level": "community", "n": 4, "note": "Forum consensus and vendor positioning."}}, "should": {"yesIf": ["You're going Stage 2", "Your factory cat is failing and you'd rather upgrade than replace", "You want the sound", "You're prepared to deal with a possible check-engine light"], "codes": ["P0420", "P0430", "P2096"], "notes": ["Catted or catless: a catless pipe is louder, smellier, will light the check-engine lamp without software, and is illegal for road use in the US (federal law, not just California). A 200-cell high-flow cat keeps most of the flow and most of the legality. This guide assumes catted.", "Even with a high-flow cat, some cars throw P0420 after a heat cycle or two. Stage 2 software from your tuner handles it; an O2 spacer is the workaround people argue about."], "confidence": {"level": "high", "n": 4, "note": "Procedure agrees across two manufacturer guides and an owner write-up; the legal point is federal regulation."}}, "parts": [{"tier": "aftermarket", "name": "3\" downpipe with high-flow cat", "pn": "see options below", "note": "Should include gasket, 4 flange nuts, bracket, clamps", "price": "$450–900", "links": []}, {"tier": "oe", "name": "Turbo-to-downpipe gasket", "pn": "in most kits", "note": "Never reuse the old one", "price": "$10", "links": []}, {"tier": "oe", "name": "Turbo flange nuts, M10 self-locking (×4)", "pn": "N 102 861 08", "note": "In most kits; buy spares, one always rounds", "price": "$8", "links": []}, {"tier": "oe", "name": "Turbo flange studs, M10 (×4)", "pn": "N 044 520 3", "note": "Only if one comes out with the nut or is chewed", "price": "$12", "links": []}, {"tier": "oe", "name": "Copper anti-seize, penetrating oil", "pn": "—", "note": "Studs, O2 threads, slip joints", "price": "$15", "links": []}], "aftermarket": [{"name": "ECS Tuning high-flow downpipe", "note": "Fits stock geometry, OE bracket and O2 positions, includes hardware and the best-documented install (with the cat-back in the same guide).", "price": "$500–650", "signal": "Best documented", "links": [{"store": "ECS install instructions", "url": "https://blog.ecstuning.com/vw-mk5-gti-ecs-valved-exhaust-system-installation-instructions/"}]}, {"name": "Integrated Engineering 3\" downpipe", "note": "V-band to a catted mid-pipe, slip-fit adapter to the stock cat-back. Full install PDF.", "price": "$600–750", "signal": "Well documented", "links": [{"store": "IE install guide (PDF)", "url": "https://cdn.performancebyie.com/guides/MK5MK6%20Downpipe%20Install%20Guide.pdf"}]}, {"name": "Unitronic 3\" downpipe", "note": "T304, V-band, 200-cell cat, OE O2 positions and an OE-style cat heat shield. Pairs with their software.", "price": "$800–1,000", "signal": "If you run Uni software", "links": []}, {"name": "CTS Turbo, APR, Eurojet", "note": "All well-regarded 3\" catted pipes with the same fitment. Eurojet's Mk5 turboback PDF is public.", "price": "$500–900", "signal": "Fine choices", "links": []}], "tools": [{"name": "Jack + stands (a lift makes this much easier)"}, {"name": "Sockets: 10, 13, 16, 17mm · 16mm wrench · M8 triple-square · T25/T30 · 5mm hex"}, {"name": "22mm O2 sensor socket or wrench, long extension for the upper flange nuts, mirror"}, {"name": "Torque wrench to 40 Nm; breaker bar; penetrating oil the night before"}, {"name": "Exhaust hanger pliers, silicone spray; second jack stand to support the pipe"}], "before": ["Soak the four turbo flange nuts and both O2 sensors with penetrating oil the night before. This is the difference between a two-hour job and a broken stud.", "Engine cold. The turbo and downpipe hold heat for an hour after a drive.", "Lay the new pipe out and test-fit every slip joint on the floor; gently round any shipping dings with a hammer.", "Get the stock pipe out over the chassis braces, so they come off. Support the pipe before you free it."], "steps": [{"n": 1, "title": "Clear the top of the engine", "blocks": [{"t": "text", "b": "Release the spring clamp on the intake duct and slide the duct off the airbox. Unplug the MAF, pop the two inlet-pipe clips, and lift the engine cover (airbox) off its four grommets, one corner at a time. (Aftermarket intake: remove enough of it to reach behind the head.)"}, {"t": "text", "b": "Behind the head, the cover plate over the turbo: remove its fasteners (10mm, 18mm and an M8 triple-square; a mirror helps), drop it off its studs, and pull it straight out."}]}, {"n": 2, "title": "Front O2 sensor and upper flange nuts", "blocks": [{"t": "text", "b": "Unplug the front O2 sensor and free its harness from two clips. Remove the sensor with a 22mm O2 socket. Then the two upper turbo-flange nuts, 16mm, on a long extension from above."}, {"t": "note", "b": "If a nut won't move, more oil and patience. A rounded nut here becomes a stud extraction with the turbo in the car."}]}, {"n": 3, "title": "Underneath: belly pan, rear O2, axle shield", "blocks": [{"t": "text", "b": "Raise the car. Belly pan off (¼-turn fasteners or Torx). Loosen the four plastic nuts on the right underbody panel (10mm), fold it down and unplug the rear O2 sensor at its connector, then remove the sensor. Remove the CV-axle heat shield (two 17mm bolts)."}]}, {"n": 4, "title": "Lower flange nuts, braces, bracket", "caution": true, "blocks": [{"t": "text", "b": "Two lower flange nuts, 16mm wrench (a 3/8-drive socket fits where 1/2 won't). Loosen the sleeve clamp at the cat-back joint (17mm) and slide it clear. Put a jack stand under the cat. Remove both chassis braces (four 13mm nuts each). Remove the two 13mm bolts holding the downpipe bracket to the crossmember."}, {"t": "warn", "b": "Once the braces and bracket are out, the stand and the four studs are all that hold a heavy, awkward pipe. Keep your body out from under it."}, {"t": "ill", "id": "downpipe-hero", "cap": "What holds it: four flange nuts, the bracket on the crossmember, the slip joint. The braces are in the way, not holding it."}]}, {"n": 5, "title": "Out with the old pipe", "timeSink": true, "blocks": [{"t": "text", "b": "Slide the pipe off the turbo studs, twist it about a quarter turn counter-clockwise, and pull it back and down out of the car. Pry the rubber-mounted bracket off the old pipe with hanger pliers or a pick; the new pipe uses the factory mounts."}]}, {"n": 6, "title": "New pipe onto the turbo", "caution": true, "blocks": [{"t": "text", "b": "Anti-seize on the four studs. New gasket on the flange with its tab at the bottom, toward the turbo. Press the new bracket into the factory rubber mounts (curved edge up) and hang the kit's bolt in it loose. Lift the pipe onto the studs, sandwiching the gasket, and start four new nuts by hand. Bracket bolts back into the crossmember."}, {"t": "torque", "label": "Turbo flange nuts (M10 ×4)", "nm": 40, "c": {"level": "high", "n": 3, "note": "40 Nm (ECS) and 30 lb-ft (IE) are the same value; owner write-up consistent."}}, {"t": "torque", "label": "Downpipe bracket bolts (×2)", "nm": 25, "c": {"level": "medium", "n": 2, "note": "ECS instructions; IE reuses factory bolts without a figure."}}, {"t": "text", "b": "Anti-seize on the kit's O2 plug and thread it into the unused bung with its washer (30 Nm), then tighten the bracket-to-pipe bolt."}]}, {"n": 7, "title": "Join it to the cat-back", "blocks": [{"t": "text", "b": "Slide the kit's reducer adapter and clamps onto the stock cat-back with anti-seize on the pipe, then the new mid-pipe extension into it, twisting to seat. Nothing tight yet.", "only": ["stockcb"]}, {"t": "text", "b": "Mate the 3-inch joint directly: slip-fit with the clamp loose, or V-band with the clamp snug but not final. Nothing tight yet.", "only": ["aftcb"]}, {"t": "text", "b": "Look along the pipe: it must sit centred, clear of the braces and the subframe, with the flex section unstressed. Then tighten the clamps. ECS: snug by hand, then torque; IE's slip-fit adapter wants to be very tight."}, {"t": "torque", "label": "Exhaust sleeve clamps", "nm": 19, "c": {"level": "varies", "n": 2, "note": "ECS: 19 Nm, no impact. IE: 'very tight, use an impact' on their slip-fit adapter. Different joint designs; follow your kit."}, "only": ["stockcb", "aftcb"]}]}, {"n": 8, "title": "Sensors, shields, braces", "blocks": [{"t": "text", "b": "Anti-seize on both O2 sensor threads and refit them (22mm, snug; they have a taper seat). Plug them in and clip the harnesses. CV shield, both chassis braces, underbody panel, belly pan. Up top: cover plate, engine cover or intake, MAF."}]}, {"n": 9, "title": "Start, check, drive, re-check", "blocks": [{"t": "text", "b": "Start it cold and put a hand near each joint feeling for puffs. Drive it. After a day or two, re-torque the flange nuts and clamps and check the pipe hasn't shifted onto a brace. If the check-engine light comes on for P0420, that's the software conversation with your tuner."}]}], "alsoReplace": [{"name": "Front and rear O2 sensors", "why": "They're out. On a car past 100k with original sensors, new ones now avoid doing this twice, and a lazy front sensor hurts fuel trims on a tuned car."}, {"name": "Turbo flange studs", "why": "If any stud is chewed or backs out with its nut, replace all four while the pipe is off. A stud that fails later means the pipe comes off again."}, {"name": "Cat-back exhaust", "why": "Same afternoon, same braces off. If you're doing both, do them together and skip the reducer adapter."}], "check": {"tab": "Cat or catless", "title": "Catted or catless?", "illId": "downpipe-hero", "illCap": "The cat sits just past the flex. High-flow means a 200-cell metallic matrix in the same spot.", "rows": [{"see": "Street car, inspections, resale", "means": "You need to pass and you'd like to breathe.", "do": "200-cell high-flow catted pipe. This guide."}, {"see": "Dedicated track car, off-road use only", "means": "Legality isn't your constraint.", "do": "Catless is louder and marginally freer-flowing; expect a check-engine light without software."}, {"see": "Just want the noise", "means": "Cat-back or resonator delete does that cheaper.", "do": "Do the cat-back first."}], "c": {"level": "community", "n": 3, "note": "Forum consensus; legal point is US federal rule."}}, "aftercare": ["Re-torque after 1–2 days.", "Exhaust smell in the cabin or a tick on cold start: gasket or a clamp, check them.", "P0420 after a few heat cycles is common with a high-flow cat; talk to your tuner before buying anything."], "disagreements": [{"topic": "Getting at the top from above", "pos": "ECS (FSI): airbox off and the cover plate behind the head. IE: turbo heat shield and coolant crossover off.", "call": "ECS's path is the FSI one. IE's crossover steps describe the TSI."}, {"topic": "Clamp tightening", "pos": "ECS: hand-snug, no impact, 19 Nm. IE: very tight, use an impact.", "call": "Different joint designs. Follow the kit; never impact a factory-style sleeve clamp."}, {"topic": "Catless", "pos": "Some forum voices treat it as normal.", "call": "Illegal on the road in the US and lights the lamp. We describe it, we don't recommend it."}], "sources": ["ECS Tuning Mk5 GTI valved exhaust installation instructions (2017)", "ECS high-flow downpipe installation PDFs", "Integrated Engineering Mk5/Mk6 downpipe install guide (PDF)", "tasteslikepetrol.net Mk5 GTI downpipe install", "Unitronic downpipe listing (OE positions)", "UroTuning turbo hardware kit (part numbers)", "Eurojet Mk5 turboback install PDF (tool list)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('catback',$j${"id": "catback", "title": "Cat-back exhaust install", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "catback-hero", "alsoFits": "2006–09 GTI, 2- and 4-door (same system) · Jetta uses a longer system", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which downpipe is on the car?", "hint": "The stock downpipe ends in a 60mm slip joint, so an aftermarket cat-back needs a reducer adapter to meet it. A 3-inch aftermarket downpipe mates directly.", "options": [{"id": "stockdp", "label": "Stock downpipe", "when": "Fit the reducer adapter and clamps that came with the cat-back"}, {"id": "aftdp", "label": "3-inch aftermarket downpipe", "when": "Direct connection, leave the adapter in the box"}]}, "glance": {"timeFirst": "2–3 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$600–1,200", "risk": "Heavy · two people · patience with alignment", "why": "The stock cat-back is quiet and heavy, with a resonator and a big muffler tuned for silence. A straight-through 3-inch system gives the car its voice and drops real weight off the back. On a stock turbo it's the sound you're paying for; the power comes with a downpipe and tune.", "note": "Vendors and owners agree: the removal is easy, the last hour is alignment."}, "heroCap": "Downpipe joint at the front, mid-pipe over the chassis brace and past the fuel tank, muffler, tips. Five rubber hangers hold it. Nothing gets tightened until it all hangs straight.", "lifespan": {"title": "When owners do this", "headline": ["Usually the first exhaust mod; often before the downpipe"], "earliest": null, "detail": "Nothing to wear out on the aftermarket side. Owners do it for sound, weight and looks. A stock system that's rusted through or rattling at 120k+ makes the decision for you.", "factors": ["Stock muffler rusting or rattling", "Downpipe going in (do both, skip the adapter)", "You want the sound now"], "inspect": ["Re-check clamps and hanger positions after the first few heat cycles"], "confidence": {"level": "community", "n": 3, "note": "Forum consensus and vendor positioning."}}, "should": {"yesIf": ["You want the car to sound like a GTI", "Stock system is rusting, dented or rattling", "You're planning a downpipe and want a 3-inch path all the way back", "You have a helper and an afternoon"], "codes": [], "notes": ["Two-door and four-door Mk5 GTIs use the same cat-back. Vendors list one part number for both; there's nothing to choose here. The Jetta is the longer car and uses a different system."], "confidence": {"level": "high", "n": 3, "note": "Fitment confirmed by vendor listings; procedure consistent across guides."}}, "parts": [{"tier": "aftermarket", "name": "Cat-back system", "pn": "see options below", "note": "Mid-pipe, muffler, tips, clamps, hangers, reducer adapter", "price": "$600–1,200", "links": []}, {"tier": "oe", "name": "Exhaust hanger rubbers (×5)", "pn": "factory", "note": "Cheap; replace any that are cracked or stretched", "price": "$6 each", "links": []}, {"tier": "oe", "name": "Silicone spray, anti-seize", "pn": "—", "note": "Hangers and slip joints", "price": "$10", "links": []}], "aftermarket": [{"name": "ECS Tuning 3\" cat-back (valved or non-valved)", "note": "T304, slip joints for adjustability, hangers welded in OE spots, adjustable tips. The valved version needs a boost tap. Install guide is the reference for this whole guide.", "price": "$900–1,200", "signal": "Best documented", "links": [{"store": "ECS install instructions", "url": "https://blog.ecstuning.com/vw-mk5-gti-ecs-valved-exhaust-system-installation-instructions/"}]}, {"name": "Borla S-Type 140248", "note": "2.5\" system, straight-through mufflers, listed for 2- and 4-door. Tamer volume, aluminised steel option. Long-running forum favourite for a daily.", "price": "$800–1,000", "signal": "Daily-driver pick", "links": [{"store": "Borla", "url": "https://www.borla.com/products/volkswagen-gti-cat-back-exhaust-system-140248"}]}, {"name": "Ultimate Racing 3\" configurable", "note": "Pick your mid-pipe (no muffler, centre muffler) and tips. Slip-fit to the stock downpipe with an adapter for their downpipe.", "price": "$700–1,000", "signal": "Build your own sound", "links": []}, {"name": "Unitronic, Milltek, APR, Eurojet", "note": "All 3\" T304 systems with OE hanger positions. Milltek is the quiet-and-refined end; Eurojet the loud end.", "price": "$800–1,500", "signal": "Fine choices", "links": []}], "tools": [{"name": "Jack + four stands, or a lift; a second person"}, {"name": "Sockets: 13, 15, 17mm · exhaust hanger pliers"}, {"name": "Torque wrench to 25 Nm; penetrating oil; silicone spray"}, {"name": "Ball-peen hammer for gently rounding shipping-dented slip joints"}], "before": ["Lay the new system out on the floor in order and test every slip joint. If one won't slide, tap the pipe end round with a hammer until it does.", "Leave the protective wrap on the mufflers until they're in the car.", "Support the exhaust from below at every stage. Never let it hang from one hanger.", "Two people to lower the old system. It is heavier than it looks."], "steps": [{"n": 1, "title": "Up on stands, split the front joint", "blocks": [{"t": "text", "b": "Car on four stands, level. Soak the sleeve-clamp nuts at the downpipe joint and the hanger rubbers. Loosen the two nuts on the sleeve clamp (17mm) and slide the sleeve forward or back to separate the joint. Don't remove the nuts."}]}, {"n": 2, "title": "Free the hangers", "blocks": [{"t": "text", "b": "Stand under the middle of the system. With hanger pliers (or a pry bar and silicone spray), pop every rubber hanger off its pin except the right-rear muffler hanger. Note where each hanger sits; the new system uses the same spots."}, {"t": "ill", "id": "catback-hero", "cap": "Five hangers. Leave the right-rear one until last; it's on a bolted bracket and holds the muffler while you work."}]}, {"n": 3, "title": "Lower the old system", "caution": true, "blocks": [{"t": "text", "b": "Loosen the two 13mm bolts on the right-rear hanger bracket, remove one, leave the other finger-tight. With your helper holding the muffler and you the front, pull the last bolt, make sure the front joint is separated, and lower the whole system as one piece, bracket attached."}, {"t": "warn", "b": "The stock system comes down as one long, heavy piece. Two people, both ready, or it comes down on one of you."}, {"t": "text", "b": "Put the right-rear bracket bolt back in on its own to hold the heat shield (23 Nm). Pry the factory hanger rubbers off the old muffler if the new system reuses them."}]}, {"n": 4, "title": "Adapter on the downpipe", "only": ["stockdp"], "blocks": [{"t": "text", "b": "Anti-seize on the downpipe's tail. Slide the kit's reducer adapter on with its clamp loose. This is what lets a 3-inch system meet the 60mm stock joint."}]}, {"n": 4, "title": "Check the 3-inch joint", "only": ["aftdp"], "blocks": [{"t": "text", "b": "No adapter. Clean the downpipe's slip end or V-band face and put anti-seize on the slip surface. Have the kit's clamp ready and loose."}]}, {"n": 5, "title": "Hang it front to back, everything loose", "blocks": [{"t": "text", "b": "Silicone spray on every hanger. Clamp over the muffler inlet, lift the muffler in, slide it onto the mid-pipe (or the adapter), and hook its brackets into the hangers. Stand under it. Then the tailpipe section, the Y-pipe with its hanger bracket, and the tips with their clamps, all twisting to seat, all loose."}, {"t": "note", "b": "The temptation is to snug each clamp as you go so it stops moving. Don't. A clamp tightened early locks a misalignment in and you'll take the whole thing apart again to fix it."}]}, {"n": 6, "title": "Align, patiently", "caution": true, "blocks": [{"t": "text", "b": "Set each hanger so the bottom hole is 10–15mm ahead of the top hole, leaning toward the front of the car; the pipe grows rearward as it heats and the hangers swing back. Then walk the system: clearance over the chassis braces at the front, around the fuel tank in the middle, at the rear crossmember, and tips centred in the bumper cut-out. Adjust slip joints by twisting, not forcing."}, {"t": "text", "b": "Snug the front clamps by hand, check again, snug the rear clamps, check again. Only then torque everything, front to back, and set the tips."}, {"t": "torque", "label": "Sleeve and slip-joint clamps", "nm": 19, "c": {"level": "medium", "n": 2, "note": "ECS instructions; no factory figure. Hand-snug first, no impact."}, "only": ["stockdp", "aftdp"]}, {"t": "warn", "b": "Anything that touches the body or a brace will resonate through the cabin at 2,000 rpm forever. Fifteen minutes of alignment now saves that."}]}, {"n": 7, "title": "Braces back, start it, drive it", "blocks": [{"t": "text", "b": "Refit any chassis brace you removed for access. Start the engine and feel each joint for leaks. Drive it, let it heat-cycle, and re-check hanger angle and clamp torque the next day. Expect the tips to have shifted a few millimetres; centre them again."}]}], "alsoReplace": [{"name": "Exhaust hanger rubbers", "why": "Original rubbers on a car this age are hard and cracked. Five new ones are a few dollars and stop the new system knocking on the body."}, {"name": "Downpipe", "why": "Same braces off, same afternoon. If Stage 2 is in your future, do both and connect them directly."}], "check": {"tab": "How loud?", "title": "How loud do you want it?", "illId": "catback-hero", "illCap": "Resonator and muffler choices are what set volume; pipe diameter mostly sets tone.", "rows": [{"see": "Daily, long drives, passengers", "means": "Drone on the highway will make you hate it.", "do": "Resonated system with a real muffler (Borla, Milltek, ECS non-valved). Avoid resonator deletes."}, {"see": "Weekend car, want to hear it", "means": "Some drone is acceptable for the sound.", "do": "3\" straight-through with a centre muffler; valved ECS if you want both."}, {"see": "Track or show", "means": "Volume is the point.", "do": "Muffler-less mid-pipe options. Check your track's dB limit first."}], "c": {"level": "community", "n": 4, "note": "Forum consensus; volume is subjective."}}, "aftercare": ["Re-check clamps and hanger angle after the first heat cycles and again at 500 miles.", "A rattle over bumps is a hanger touching or a loose heat shield.", "Drone that appears later means a slip joint has crept; re-align."], "disagreements": [{"topic": "2-door vs 4-door", "pos": "Assumed to differ.", "call": "Same system on the Mk5 GTI; the Jetta differs."}, {"topic": "Tighten as you go?", "pos": "Instinct says yes.", "call": "Every guide says no. Loose until aligned."}], "sources": ["ECS Tuning Mk5 GTI valved exhaust installation instructions (2017)", "Borla 140248 fitment listing", "ECS, Ultimate Racing and Malian cat-back listings (adapter/fitment)", "IE Mk7 cat-back guide (technique)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
